:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --primary-hover: #ff6b81;
  --secondary: #0f3460;
  --text: #eaeaea;
  --text-muted: #a0a0b0;
  --accent: #f9c74f;
  --focus-ring: #f9c74f;
  --border-radius: 12px;
  --font-stack: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-stack);
  font-size: 16px;
  background-color: var(--bg);
  background-image: radial-gradient(circle at 20% 30%, #2a2a4a 0%, transparent 40%),
                    radial-gradient(circle at 80% 70%, #2a2a4a 0%, transparent 40%);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-card {
  background-color: var(--card-bg);
  border-radius: var(--border-radius);
  padding: 24px 20px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  border: 2px solid var(--secondary);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.game-header h1 {
  font-size: 1.6rem;
  text-align: center;
  color: var(--accent);
  letter-spacing: 1px;
  text-transform: uppercase;
}

.scoreboard {
  display: flex;
  justify-content: space-around;
  background-color: var(--secondary);
  border-radius: var(--border-radius);
  padding: 12px;
}

.score-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.score-label {
  font-size: 0.9rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.score-value {
  font-size: 2rem;
  font-weight: bold;
  color: var(--accent);
  line-height: 1;
}

.choices {
  display: flex;
  gap: 10px;
  justify-content: center;
  flex-wrap: wrap;
}

.choice-btn {
  flex: 1;
  min-width: 80px;
  padding: 16px 8px;
  background-color: var(--secondary);
  border: 2px solid transparent;
  border-radius: var(--border-radius);
  color: var(--text);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  font-family: inherit;
  font-size: 1rem;
  transition: background-color 0.15s, border-color 0.15s, transform 0.1s;
}

.choice-btn .icon {
  font-size: 2rem;
  line-height: 1;
}

.choice-btn .label {
  font-size: 0.9rem;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.choice-btn:hover {
  background-color: var(--primary);
  border-color: var(--primary-hover);
}

.choice-btn:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

.choice-btn:active {
  transform: scale(0.96);
  background-color: var(--primary-hover);
}

.result-area {
  background-color: var(--secondary);
  border-radius: var(--border-radius);
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.picks {
  display: flex;
  justify-content: space-around;
}

.pick {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.pick-label {
  font-size: 0.8rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
}

.pick-icon {
  font-size: 2.5rem;
  line-height: 1;
  min-height: 2.5rem;
}

.round-result {
  text-align: center;
  font-size: 1.2rem;
  font-weight: bold;
  color: var(--accent);
  min-height: 1.5em;
}

.game-footer {
  display: flex;
  justify-content: center;
}

.reset-btn {
  background-color: var(--primary);
  color: var(--text);
  border: none;
  border-radius: var(--border-radius);
  padding: 12px 24px;
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: background-color 0.15s, transform 0.1s;
}

.reset-btn:hover {
  background-color: var(--primary-hover);
}

.reset-btn:focus-visible {
  outline: 3px solid var(--focus-ring);
  outline-offset: 2px;
}

.reset-btn:active {
  transform: scale(0.96);
}

@media (max-width: 400px) {
  .game-card {
    padding: 16px 12px;
  }
  .game-header h1 {
    font-size: 1.3rem;
  }
  .choice-btn {
    padding: 12px 4px;
    min-width: 60px;
  }
  .choice-btn .icon {
    font-size: 1.6rem;
  }
  .choice-btn .label {
    font-size: 0.75rem;
  }
  .pick-icon {
    font-size: 2rem;
  }
  .score-value {
    font-size: 1.6rem;
  }
}

'use strict';

const choices = ['rock', 'paper', 'scissors'];
const icons = { rock: '✊', paper: '✋', scissors: '✌️' };

const playerScoreEl = document.getElementById('player-score');
const computerScoreEl = document.getElementById('computer-score');
const playerPickEl = document.getElementById('player-pick');
const computerPickEl = document.getElementById('computer-pick');
const roundResultEl = document.getElementById('round-result');
const resetBtn = document.getElementById('reset-btn');
const choiceButtons = document.querySelectorAll('.choice-btn');

let playerScore = 0;
let computerScore = 0;

function getComputerChoice() {
  return choices[Math.floor(Math.random() * choices.length)];
}

function determineWinner(player, computer) {
  if (player === computer) return 'tie';
  if (
    (player === 'rock' && computer === 'scissors') ||
    (player === 'paper' && computer === 'rock') ||
    (player === 'scissors' && computer === 'paper')
  ) {
    return 'player';
  }
  return 'computer';
}

function updateScores() {
  playerScoreEl.textContent = playerScore;
  computerScoreEl.textContent = computerScore;
}

function playRound(playerChoice) {
  const computerChoice = getComputerChoice();
  const winner = determineWinner(playerChoice, computerChoice);

  playerPickEl.textContent = icons[playerChoice];
  computerPickEl.textContent = icons[computerChoice];

  if (winner === 'player') {
    playerScore++;
    roundResultEl.textContent = 'You win this round!';
  } else if (winner === 'computer') {
    computerScore++;
    roundResultEl.textContent = 'Computer wins this round!';
  } else {
    roundResultEl.textContent = "It's a tie!";
  }

  updateScores();
}

function resetGame() {
  playerScore = 0;
  computerScore = 0;
  updateScores();
  playerPickEl.textContent = '—';
  computerPickEl.textContent = '—';
  roundResultEl.textContent = 'Make your move!';
}

choiceButtons.forEach((btn) => {
  btn.addEventListener('click', () => {
    const choice = btn.dataset.choice;
    if (choices.includes(choice)) {
      playRound(choice);
    }
  });
});

resetBtn.addEventListener('click', resetGame);

updateScores();
